export const SEARCH_FILTERS_PATH = 'web/src/search/filters.ts';
export const DATE_HELPERS_PATH = 'web/src/lib/dates.ts';
export const WEEK_NUMBER_RETURN_LINE = 42;

const SEARCH_FILTERS_LINES: readonly string[] = [
  "import type { PriceBound } from './price-bound';",
  "import type { RewrittenQuery, SearchFilters } from './types';",
  '',
  'const CENTS_PER_EURO = 100;',
  "const COLOURS = ['black', 'blue', 'green', 'grey', 'red', 'white', 'yellow'] as const;",
  '',
  'export type Colour = (typeof COLOURS)[number];',
  '',
  'export function isColour(word: string): word is Colour {',
  '  return COLOURS.some((colour) => colour === word);',
  '}',
  '',
  'export function filtersFromRewrite(rewrite: RewrittenQuery): SearchFilters {',
  '  const filters: SearchFilters = {};',
  '  if (rewrite.colour !== null && isColour(rewrite.colour)) filters.colour = rewrite.colour;',
  '  if (rewrite.price !== null) applyPriceBound(filters, rewrite.price);',
  '  return filters;',
  '}',
  '',
  'function applyPriceBound(filters: SearchFilters, bound: PriceBound): void {',
  "  if (bound.direction === 'max') {",
  '    filters.maxPriceCents = bound.cents;',
  '  } else {',
  '    filters.minPriceCents = bound.cents;',
  '  }',
  '}',
  '',
  'export function priceLabel(cents: number): string {',
  '  const euros = cents / CENTS_PER_EURO;',
  '  // the catalogue stores prices in cents, the interface shows euros',
  "  return Number.isInteger(euros) ? `${euros} €` : `${euros.toFixed(2)} €`;",
  '}',
];

export const SEARCH_FILTERS_COMMENT_LINE = SEARCH_FILTERS_LINES.findIndex((line) => line.trim().startsWith('//')) + 1;

